"""
知识树处理工具类
提供知识树的基础操作方法
"""

import hashlib
import threading
from typing import Dict, List, Any, Optional, Tuple
from loguru import logger
from urllib.parse import urlparse


class TreeNodeProcessor:
    """知识树节点处理器"""

    def __init__(self):
        self._lock = threading.Lock()

    @staticmethod
    def get_node_list(tree: Dict[str, Any], with_path: bool = False) -> List[Dict]:
        """递归获取树中所有节点

        Args:
            tree: 知识树字典
            with_path: 是否包含路径信息

        Returns:
            List[Dict]: 节点列表
        """
        def _traverse(node: Dict, path: str = "", result: List = None) -> List:
            if result is None:
                result = []

            # 处理当前节点
            current_node = node.copy()
            if with_path and path:
                current_node['upstream_path'] = path
            elif with_path:
                current_node['upstream_path'] = node.get('name', '')

            result.append(current_node)

            # 递归处理子节点
            if 'children' in node and node['children']:
                current_path = path + '->' + node['name'] if path else node['name']
                for child in node['children']:
                    _traverse(child, current_path, result)

            return result

        try:
            return _traverse(tree)
        except Exception as e:
            logger.error(f"获取节点列表失败: {e}")
            return []

    @staticmethod
    def get_leaf_node_list(tree: Dict[str, Any]) -> List[Dict]:
        """获取所有叶子节点

        Args:
            tree: 知识树字典

        Returns:
            List[Dict]: 叶子节点列表
        """
        try:
            TreeNodeProcessor.add_base_node_labeling(tree)
            tree_node_list = TreeNodeProcessor.get_node_list(tree, with_path=True)
            leaf_list = [node for node in tree_node_list if not node.get('children', [])]
            return leaf_list
        except Exception as e:
            logger.error(f"获取叶子节点失败: {e}")
            return []

    @staticmethod
    def add_base_node_labeling(tree: Dict[str, Any]) -> Dict[str, Any]:
        """给节点添加基础标签

        Args:
            tree: 知识树字典

        Returns:
            Dict: 标签化后的树
        """
        tree['label'] = 'knowledge'
        if 'children' in tree and tree['children']:
            for child in tree['children']:
                TreeNodeProcessor.add_base_node_labeling(child)
        return tree

    @staticmethod
    def filter_null_nodes(tree: Dict[str, Any]) -> Dict[str, Any]:
        """过滤空节点

        Args:
            tree: 知识树字典

        Returns:
            Dict: 过滤后的树
        """
        try:
            valid_children = []
            if 'children' in tree:
                for child in tree['children']:
                    if child.get('name', '').strip():
                        filtered_child = TreeNodeProcessor.filter_null_nodes(child)
                        valid_children.append(filtered_child)
                tree['children'] = valid_children
            return tree
        except Exception as e:
            logger.error(f"过滤空节点失败: {e}")
            return tree

    @staticmethod
    def add_source_list_recursive(tree: Dict[str, Any], source_list: List[Dict]):
        """递归添加源列表

        Args:
            tree: 知识树字典
            source_list: 源信息列表
        """
        try:
            if 'sourceList' not in tree:
                tree['sourceList'] = source_list.copy()
            else:
                tree['sourceList'].extend(source_list)

            if 'children' in tree:
                for child in tree['children']:
                    TreeNodeProcessor.add_source_list_recursive(child, source_list)
        except Exception as e:
            logger.error(f"添加源列表失败: {e}")

    @staticmethod
    def build_paper_node(paper: Dict, res_llm: Dict, paper_title: str, leaf_name: str) -> Dict:
        """构建文献节点

        Args:
            paper: 文献信息
            res_llm: LLM处理结果
            paper_title: 文献标题
            leaf_name: 叶子节点名称

        Returns:
            Dict: 文献节点
        """
        try:
            return {
                "name": paper_title,
                "nodeUid": paper.get("uniqueId", ""),
                "label": 'paper',
                "description": f"关于【{leaf_name}】的研究文献有【{paper_title}】。" + 
                             res_llm.get("paper_abstract", {}).get('description', ''),
                "children": TreeNodeProcessor.build_paper_children(paper, res_llm)
            }
        except Exception as e:
            logger.error(f"构建文献节点失败: {e}")
            return {}

    @staticmethod
    def build_paper_children(paper: Dict, res_llm: Dict, knowledge_url: str = '') -> List[Dict]:
        """构建文献子节点

        Args:
            paper: 文献信息
            res_llm: LLM处理结果
            knowledge_url: 知识链接

        Returns:
            List[Dict]: 文献子节点列表
        """
        try:
            paper_title = str(paper.get("paper_title", ""))
            paper_url = str(paper.get("paper_url", ""))
            paper_channel = str(paper.get("paper_channel", ""))

            # 渠道别名映射
            channel_alias = (['网络资源', '互联网资源', '网络', '互联网'] 
                           if paper_channel == 'internet' 
                           else ['知识库', '知识库资源'])

            # 处理年份信息
            publish_time = paper.get("publish_time", "")
            if '-' in str(publish_time):
                paper_year = str(publish_time).split('-')[0]
            else:
                paper_year = str(publish_time)
            paper_year = paper_year or res_llm.get("paper_year", {}).get('name', '')

            # 处理作者信息
            paper_authors = '、'.join(paper.get("paper_authors", []))
            paper_authors = paper_authors or res_llm.get("paper_author", {}).get('name', '')

            # 处理关键词
            paper_keyword = '、'.join(paper.get("paper_keyword", []))
            paper_keyword = paper_keyword or res_llm.get("keywords", {}).get('name', '')

            # 处理摘要
            paper_abstract = str(paper.get("paper_abstract", ""))
            paper_abstract = paper_abstract or res_llm.get("paper_abstract", {}).get('name', '')

            return [
                {
                    "name": paper_channel, 
                    "label": 'paper_channel', 
                    'alisaList': channel_alias, 
                    "children": [], 
                    'description': f"《{paper_title}》文献的渠道为【{paper_channel}】"
                },
                {
                    "name": paper_url, 
                    "label": 'paper_url', 
                    "children": [], 
                    'description': f"《{paper_title}》文献的文件链接为【{paper_url}】"
                },
                {
                    "name": paper_year, 
                    "label": 'paper_year', 
                    "children": [], 
                    'description': f"《{paper_title}》文献的年份为【{paper_year}】"
                },
                {
                    "name": paper_authors, 
                    "label": 'paper_authors', 
                    "children": [], 
                    "description": f"《{paper_title}》文献的作者信息为【{paper_authors}】"
                },
                {
                    "name": paper_keyword, 
                    "label": 'paper_keyword', 
                    "children": [], 
                    "description": f"《{paper_title}》文献的关键词信息为【{paper_keyword}】"
                },
                {
                    "name": paper_abstract, 
                    "label": 'paper_abstract', 
                    "children": [], 
                    "description": f"《{paper_title}》文献的摘要为：" + 
                                 res_llm.get("paper_abstract", {}).get('description', '')
                },
                {
                    "name": res_llm.get("paper_dateset", {}).get('name', ''), 
                    "label": 'paper_dataset', 
                    "children": [], 
                    "description": f"《{paper_title}》文献的数据集信息为：" + 
                                 res_llm.get("paper_dataset", {}).get('description', '')
                },
                {
                    "name": res_llm.get("research_innovations", {}).get('name', ''), 
                    "label": 'research_innovations', 
                    "children": [], 
                    "description": f"《{paper_title}》文献的创新点为：" + 
                                 res_llm.get("research_innovations", {}).get('description', '')
                },
                {
                    "name": res_llm.get("research_significance", {}).get('name', ''), 
                    "label": 'research_significance', 
                    "children": [], 
                    "description": f"《{paper_title}》文献的价值与意义为：" + 
                                 res_llm.get("research_significance", {}).get('description', '')
                },
                {
                    "name": res_llm.get("key_conclusions", {}).get('name', ''), 
                    "label": 'paper_key_conclusions', 
                    "children": [], 
                    "description": f"《{paper_title}》文献的核心结论为：" + 
                                 res_llm.get("key_conclusions", {}).get('description', '')
                }
            ]
        except Exception as e:
            logger.error(f"构建文献子节点失败: {e}")
            return []


class ContentProcessor:
    """内容处理器"""

    @staticmethod
    def get_paper_source_list(paper: Dict) -> List[Dict]:
        """获取文献源信息列表

        Args:
            paper: 文献信息字典

        Returns:
            List[Dict]: 源信息列表
        """
        try:
            return [{
                "title": paper.get("block_title", ""),
                "sourceId": paper.get('source_id', ""),
                "sourceName": paper.get('source_name', ""),
                "sourceType": paper.get('resource_type_en', ""),
                "id": paper.get("id", ""),
                "segId": paper.get("segId", ""),
                "url": str(paper.get("paper_url", ""))
            }]
        except Exception as e:
            logger.error(f"获取文献源信息失败: {e}")
            return []

    @staticmethod
    def is_valid_url(url: str) -> bool:
        """检查URL是否有效

        Args:
            url: 待检查的URL

        Returns:
            bool: 是否有效
        """
        try:
            result = urlparse(url)
            return all([result.scheme, result.netloc])
        except (ValueError, AttributeError):
            return False

    @staticmethod
    def reset_paper_tree(tree: Dict) -> Dict:
        """重置文献树结构

        Args:
            tree: 原始树结构

        Returns:
            Dict: 重置后的树结构
        """
        new_res = {}
        try:
            for res in tree.get('result', []):
                for key in res.keys():
                    if key != "summary":
                        new_res[key] = {
                            "name": res.get("summary", ''),
                            "description": res[key]
                        }
            return new_res
        except Exception as e:
            logger.error(f"文献提取结果字段异常: {e}")
            return new_res

    @staticmethod
    def process_special_fields(res_llm: Dict, paper_title: str, params_en_list: List[str]) -> List[Dict]:
        """处理特殊字段（科研脉络字段）

        Args:
            res_llm: LLM处理结果
            paper_title: 文献标题
            params_en_list: 参数列表（英文）

        Returns:
            List[Dict]: 特殊字段列表
        """
        try:
            from .project_configs import NODE_LABEL_NAME

            special_res = []
            for item in params_en_list:
                field_data = {
                    "name": res_llm.get(item, {}).get('name', ''),
                    "label": item,
                    "children": [],
                    "description": f"《{paper_title}》文献的{NODE_LABEL_NAME.get(item, item)}信息为：" +
                                 res_llm.get(item, {}).get('description', '')
                }
                special_res.append(field_data)

            return special_res
        except Exception as e:
            logger.error(f"处理特殊字段失败: {e}")
            return []


class UtilityFunctions:
    """工具函数集合"""

    @staticmethod
    def get_md5_id(text: str) -> str:
        """生成MD5哈希值

        Args:
            text: 输入文本

        Returns:
            str: MD5哈希值
        """
        try:
            return hashlib.md5(text.encode('utf-8')).hexdigest()
        except Exception as e:
            logger.error(f"生成MD5失败: {e}")
            return ""

    @staticmethod
    def safe_get_nested_value(data: Dict, keys: List[str], default: Any = None) -> Any:
        """安全获取嵌套字典值

        Args:
            data: 字典数据
            keys: 键路径列表
            default: 默认值

        Returns:
            Any: 获取到的值或默认值
        """
        try:
            current = data
            for key in keys:
                current = current[key]
            return current
        except (KeyError, TypeError, AttributeError):
            return default

    @staticmethod
    def merge_dicts_safely(*dicts: Dict) -> Dict:
        """安全合并多个字典

        Args:
            *dicts: 要合并的字典

        Returns:
            Dict: 合并后的字典
        """
        try:
            result = {}
            for d in dicts:
                if isinstance(d, dict):
                    result.update(d)
            return result
        except Exception as e:
            logger.error(f"字典合并失败: {e}")
            return {}

    @staticmethod
    def clean_text(text: str, max_length: Optional[int] = None) -> str:
        """清理文本内容

        Args:
            text: 原始文本
            max_length: 最大长度限制

        Returns:
            str: 清理后的文本
        """
        try:
            if not isinstance(text, str):
                text = str(text)

            # 移除多余的空白字符
            text = ' '.join(text.split())

            # 长度限制
            if max_length and len(text) > max_length:
                text = text[:max_length] + "..."

            return text
        except Exception as e:
            logger.error(f"文本清理失败: {e}")
            return ""

    @staticmethod
    def validate_tree_structure(tree: Dict) -> Tuple[bool, List[str]]:
        """验证树结构的完整性

        Args:
            tree: 知识树字典

        Returns:
            Tuple[bool, List[str]]: (是否有效, 错误信息列表)
        """
        errors = []

        try:
            # 检查必需字段
            required_fields = ['name']
            for field in required_fields:
                if field not in tree:
                    errors.append(f"缺少必需字段: {field}")

            # 检查名称有效性
            if not tree.get('name', '').strip():
                errors.append("节点名称不能为空")

            # 递归检查子节点
            if 'children' in tree and isinstance(tree['children'], list):
                for i, child in enumerate(tree['children']):
                    if isinstance(child, dict):
                        child_valid, child_errors = UtilityFunctions.validate_tree_structure(child)
                        if not child_valid:
                            errors.extend([f"子节点{i}: {err}" for err in child_errors])
                    else:
                        errors.append(f"子节点{i}格式错误")

            return len(errors) == 0, errors

        except Exception as e:
            errors.append(f"验证过程异常: {str(e)}")
            return False, errors


class AggregationProcessor:
    """聚合处理器"""

    @staticmethod
    def recu_agg(kn_name: str, param_list: List[str], paper_dict_list: List[Dict], 
                idx: int = 0, new_res_list: Optional[List] = None) -> List:
        """递归聚合处理

        Args:
            kn_name: 知识点名称
            param_list: 参数列表
            paper_dict_list: 文献字典列表
            idx: 当前索引
            new_res_list: 结果列表

        Returns:
            List: 聚合后的结果列表
        """
        try:
            from .project_configs import NODE_RELATION_CN
            from collections import defaultdict

            # 初始化结果列表
            if new_res_list is None:
                new_res_list = []

            # 递归终止条件
            if idx >= len(param_list):
                return new_res_list

            param = param_list[idx]
            param_cn = NODE_RELATION_CN.get(param, param)
            field_dict = defaultdict(list)

            # 按字段分组
            for paper_dict in paper_dict_list:
                for child in paper_dict.get('children', []):
                    if child.get('label') == param:
                        std_cls = child.get('std_cls', child.get('name', ''))
                        field_dict[std_cls].append(paper_dict)
                        break

            # 处理每个分组
            for field, field_papers in field_dict.items():
                paper_num = len(field_papers)
                temp_field_dict = {
                    "name": f"'{kn_name}'的{param_cn}是{field}",
                    "label": param,
                    "children": [],
                    "description": f"'{kn_name}'的{param_cn}是{field}，共涉及{paper_num}篇文献"
                }
                new_res_list.append(temp_field_dict)

                # 递归处理或直接添加文献
                if idx == len(param_list) - 1:
                    temp_field_dict["children"] = field_papers
                else:
                    AggregationProcessor.recu_agg(
                        kn_name, param_list, field_papers, 
                        idx + 1, temp_field_dict['children']
                    )

            return new_res_list

        except Exception as e:
            logger.error(f"递归聚合处理失败: {e}")
            return new_res_list or []


# 导出主要类和函数
__all__ = [
    'TreeNodeProcessor',
    'ContentProcessor', 
    'UtilityFunctions',
    'AggregationProcessor'
]
